(()=>{
const smileTimers=new WeakMap();
function smile(detail){const id=detail.answer==='practiceAnswer'?'soloAvatar':/^answer[01]$/.test(detail.answer||'')?'sharedAvatar'+detail.answer.at(-1):detail.answer==='netAnswer'&&/^netScore[01]$/.test(detail.score||'')?'netAvatar'+detail.score.at(-1):null;const target=id&&document.getElementById(id);if(!target?.dataset.avatarKey||!window.KukuAvatar)return;try{const key=target.dataset.avatarKey,avatar=JSON.parse(key),size=Number(target.dataset.avatarSize)||(id.startsWith('netAvatar')?66:76);clearTimeout(smileTimers.get(target));target.innerHTML=window.KukuAvatar.svg({...avatar,face:'happy'},size);smileTimers.set(target,setTimeout(()=>{if(target.dataset.avatarKey===key)target.innerHTML=window.KukuAvatar.svg(avatar,size);smileTimers.delete(target)},800))}catch{}}
function animate(id,kind){const x=document.getElementById(id);if(!x)return;x.classList.remove('correct','wrong','bump');void x.offsetWidth;x.classList.add(kind)}
function celebrate(count){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const root=document.getElementById('celebration');for(let i=0;i<count;i++){const star=document.createElement('span');star.className='confetti';star.textContent=i%3?'★':'✦';star.style.left=(18+Math.random()*64)+'%';star.style.color=['#edbc51','#ef847a','#64bfd4','#a5c98b'][i%4];star.style.animationDelay=(Math.random()*.1)+'s';star.style.fontSize=(14+Math.random()*12)+'px';root.append(star);setTimeout(()=>star.remove(),1000)}}
window.addEventListener('kuku-feedback',e=>{const d=e.detail;if(d.type==='correct'){animate(d.answer,'correct');animate(d.score,'bump');smile(d);celebrate(6)}else if(d.type==='wrong'){animate(d.answer,'wrong')}else if(d.type==='finish')celebrate(12)});
})();
